package com.sbcs.detect.dungeon;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Every reward chest's pool - {@code assets/sbcs/dungeon_pool.json}, generated by tools/gen_dungeon_pool.py from the
 * wiki's loot tables (tools/fixtures/dungeon_loot), SkyOcean's pools (MIT) where a wiki table was cut or missing, and
 * the NEU item repo for looks. Pure (Gson only). Weights are Hypixel's: they decide what goes past on the reel and what
 * a test chest holds. Each entry also has the wiki's added cost (what it puts on the chest's price). Also the name
 * table Croesus's "Contents" lines are priced through. The dyes are not pool rolls; they are only looks
 * ({@code extras}).
 */
public final class DungeonPool {

    public record Entry(Loot look, int weight, long cost) {}

    private final Map<String, List<Entry>> pools = new HashMap<>();
    private final Map<String, Loot> byKey = new HashMap<>();
    private final Map<String, String> nameToKey = new HashMap<>();
    private final Map<String, String> sources = new HashMap<>();
    private final Map<String, Integer> totals = new HashMap<>();

    public static DungeonPool parse(String json) {
        DungeonPool p = new DungeonPool();
        JsonObject all = JsonParser.parseString(json).getAsJsonObject();
        if (all.has("extras")) {
            for (var e : all.getAsJsonObject("extras").entrySet()) p.add(e.getValue().getAsJsonObject());
        }
        JsonObject root = all.has("pools") ? all.getAsJsonObject("pools") : new JsonObject();
        for (var floor : root.entrySet()) {
            for (var tier : floor.getValue().getAsJsonObject().entrySet()) {
                List<Entry> rows = new ArrayList<>();
                for (JsonElement e : tier.getValue().getAsJsonArray()) {
                    JsonObject o = e.getAsJsonObject();
                    rows.add(new Entry(p.add(o), Math.max(1, o.get("weight").getAsInt()), o.has("cost") ? o.get("cost").getAsLong() : 0));
                }
                p.pools.put(key(floor.getKey(), tier.getKey()), rows);
            }
        }
        for (String part : new String[]{"sources", "totals"}) {
            if (!all.has(part)) continue;
            for (var floor : all.getAsJsonObject(part).entrySet()) {
                for (var tier : floor.getValue().getAsJsonObject().entrySet()) {
                    if (part.equals("sources")) p.sources.put(key(floor.getKey(), tier.getKey()), tier.getValue().getAsString());
                    else p.totals.put(key(floor.getKey(), tier.getKey()), tier.getValue().getAsInt());
                }
            }
        }
        return p;
    }

    private static String key(String floor, String tier) {
        return floor + ":" + tier.toLowerCase(java.util.Locale.ROOT);
    }

    /** One item's look, kept by its key and its names. */
    private Loot add(JsonObject o) {
        String key = o.get("key").getAsString(), name = o.get("name").getAsString();
        int colour = o.has("color") && o.get("color").getAsInt() != 0 ? o.get("color").getAsInt() : -1;
        Loot look = new Loot(key, name, 1, false, str(o, "item"), str(o, "model"), str(o, "skin"),
                o.has("glint") || o.has("book"), colour, null);
        byKey.putIfAbsent(key, look);
        nameToKey.putIfAbsent(name, key);
        String book = PriceKeys.bookName(key);
        if (book != null) nameToKey.putIfAbsent("Enchanted Book (" + book + ")", key);
        return byKey.get(key);
    }

    private static String str(JsonObject o, String k) {
        return o.has(k) ? o.get(k).getAsString() : null;
    }

    /**
     * The pool of a floor's chest. Every floor has its own Wood to Obsidian, and F5-F7 / M5-M7 a Bedrock; a chest
     * that does not exist (Bedrock below Floor V) borrows its floor's Obsidian, then Floor VII's; the Entrance has Floor I's.
     */
    public List<Entry> pool(DungeonFloor floor, ChestTier tier) {
        String f = floor == null ? "F7" : floor.poolKey();
        List<Entry> l = pools.get(key(f, tier.name()));
        if (l == null || l.isEmpty()) l = pools.get(key(f, "obsidian"));
        if (l == null || l.isEmpty()) l = pools.get(key("F7", "obsidian"));
        return l == null ? List.of() : l;
    }

    /** Where this chest's pool came from ("wiki", "SkyOcean", "derived ..."), or null if it has none of its own. */
    public String source(DungeonFloor floor, ChestTier tier) {
        return floor == null ? null : sources.get(key(floor.poolKey(), tier.name()));
    }

    /** The wiki's total weight for this chest (weight / first-roll chance), or null where no wiki table was read. */
    public Integer total(DungeonFloor floor, ChestTier tier) {
        return floor == null ? null : totals.get(key(floor.poolKey(), tier.name()));
    }

    /** How an item of this key looks, or null if the pool does not hold it. */
    public Loot look(String key) {
        return key == null ? null : byKey.get(key);
    }

    public Map<String, String> names() {
        return nameToKey;
    }
}
